insert into public.questions (slug, category, executive_track, category_slug, difficulty, number_friendliness, operation_count, publication_status, prompt, instruction, unit, correct_answer, answer_tolerance, hint)
values
  ('ceo-revenue-growth', 'growth and market share', 'ceo', 'growth-and-market-share', 1, 1, 2, 'published', 'Revenue increases from $80M to $100M. What is the percentage growth?', 'Enter the percentage growth.', '%', 25, 0.01, 'Calculate the $20M increase, then divide it by the original $80M.'),
  ('ceo-resource-allocation-remaining', 'resource allocation', 'ceo', 'resource-allocation', 1, 1, 2, 'published', 'A company has a $120M investment budget. It allocates $35M to expansion and $25M to technology. How much remains?', 'Enter the remaining budget.', '$M', 60, 0.01, 'Subtract both investments from the total budget.'),
  ('ceo-subscription-revenue', 'pricing and profitability', 'ceo', 'pricing-and-profitability', 1, 1, 2, 'published', 'A company sells 20,000 subscriptions at $50 each. What revenue does it generate?', 'Enter revenue in millions of dollars.', '$M', 1, 0.01, 'Multiply subscriptions by price, then convert dollars to millions.'),
  ('ceo-market-share', 'growth and market share', 'ceo', 'growth-and-market-share', 1, 1, 2, 'published', 'A company generates $30M in a market worth $200M. What is its market share?', 'Enter the market share as a percentage.', '%', 15, 0.01, 'Divide company revenue by total market revenue.'),
  ('ceo-margin-comparison', 'competitive benchmarking', 'ceo', 'competitive-benchmarking', 1, 1, 1, 'published', 'Your operating margin is 12%, while a competitor''s margin is 8%. What is the difference in percentage points?', 'Enter the difference in percentage points.', 'points', 4, 0.01, 'Subtract the competitor''s margin from your margin.'),
  ('ceo-weighted-portfolio-margin', 'portfolio decisions', 'ceo', 'portfolio-decisions', 2, 2, 3, 'published', 'A division representing 60% of revenue earns a 25% margin. The remaining 40% earns a 10% margin. What is the company''s weighted operating margin?', 'Enter the weighted operating margin.', '%', 19, 0.1, 'Multiply each margin by its revenue weight, then add the results.'),
  ('ceo-post-synergy-acquisition-multiple', 'acquisitions and divestitures', 'ceo', 'acquisitions-and-divestitures', 2, 2, 2, 'published', 'A company pays $240M for a business earning $24M annually. It expects $6M of annual synergies. What multiple is it paying on post-synergy earnings?', 'Enter the post-synergy earnings multiple.', 'x', 8, 0.01, 'Add synergies to earnings, then divide the purchase price by the result.'),
  ('ceo-buyback-capacity', 'capital allocation', 'ceo', 'capital-allocation', 2, 2, 3, 'published', 'A company has $100M in available cash. It repays $30M of debt and retains a $25M reserve. If shares trade at $15, how many million shares can it repurchase?', 'Enter the number of shares in millions.', 'M shares', 3, 0.01, 'Find the remaining cash, then divide it by the share price.'),
  ('ceo-probability-weighted-profit', 'scenario planning', 'ceo', 'scenario-planning', 3, 3, 5, 'published', 'Next year''s operating profit could be $30M with 40% probability, $20M with 40% probability, or $5M with 20% probability. What is the expected operating profit?', 'Enter the expected operating profit.', '$M', 21, 0.01, 'Multiply each outcome by its probability, then add the three weighted results.'),
  ('ceo-enterprise-to-equity-value', 'enterprise valuation', 'ceo', 'enterprise-valuation', 3, 3, 4, 'published', 'A company generates $300M of revenue at a 12% EBITDA margin. It is valued at 8 times EBITDA and has $70M of debt and $10M of cash. What is its equity value?', 'Enter the equity value in millions of dollars.', '$M', 228, 0.01, 'Calculate EBITDA, apply the multiple, subtract debt, then add cash.'),
  ('coo-capacity-utilization', 'capacity and utilization', 'coo', 'capacity-and-utilization', 1, 1, 1, 'published', 'A plant can produce 8,000 units per week and currently produces 6,000. What is capacity utilization?', 'Enter utilization as a percentage.', '%', 75, 0.01, 'Divide actual output by maximum output.'),
  ('coo-daily-throughput', 'throughput and bottlenecks', 'coo', 'throughput-and-bottlenecks', 1, 1, 1, 'published', 'A line produces 1,200 units during an 8-hour shift. What is its hourly throughput?', 'Enter units produced per hour.', 'units/hour', 150, 0.01, 'Divide total units by shift hours.'),
  ('coo-productivity-improvement', 'productivity', 'coo', 'productivity', 1, 1, 2, 'published', 'Output per employee rises from 40 to 50 units per day. What is the productivity increase?', 'Enter the percentage increase.', '%', 25, 0.01, 'Find the 10-unit increase and divide it by the original 40.'),
  ('coo-production-yield', 'yield and scrap', 'coo', 'yield-and-scrap', 1, 1, 2, 'published', 'A factory starts 1,000 units and 950 pass inspection. What is its production yield?', 'Enter yield as a percentage.', '%', 95, 0.01, 'Divide accepted units by units started.'),
  ('coo-inventory-turns', 'inventory turns', 'coo', 'inventory-turns', 1, 2, 1, 'published', 'Annual cost of goods sold is $24M and average inventory is $4M. How many inventory turns does the company achieve?', 'Enter annual inventory turns.', 'x', 6, 0.01, 'Divide annual cost of goods sold by average inventory.'),
  ('coo-weighted-cycle-time', 'lead and cycle times', 'coo', 'lead-and-cycle-times', 2, 2, 3, 'published', 'Seventy percent of orders take 2 days and 30% take 5 days. What is the weighted average cycle time?', 'Enter the average number of days.', 'days', 2.9, 0.05, 'Weight each cycle time by its share of orders, then add.'),
  ('coo-service-level-shortfall', 'service levels', 'coo', 'service-levels', 2, 2, 3, 'published', 'A team receives 2,000 orders, ships 1,840 on time, and targets a 95% on-time rate. By how many percentage points does actual performance miss the target?', 'Enter the shortfall in percentage points.', 'points', 3, 0.01, 'Calculate the actual on-time percentage, then compare it with 95%.'),
  ('coo-cost-reduction-savings', 'cost reduction', 'coo', 'cost-reduction', 2, 2, 3, 'published', 'A process costs $12 per unit for 500,000 units. A redesign lowers unit cost by 15%. What annual savings does it create?', 'Enter annual savings in millions of dollars.', '$M', 0.9, 0.01, 'Find the saving per unit, then multiply by volume and convert to millions.'),
  ('coo-mixed-line-bottleneck', 'throughput and bottlenecks', 'coo', 'throughput-and-bottlenecks', 3, 2, 4, 'published', 'A three-step process can handle 120, 90, and 100 units per hour. It runs 8 hours at 80% effective uptime. What is maximum daily output?', 'Enter maximum daily output.', 'units', 576, 0.01, 'Use the slowest step as hourly capacity, then apply hours and uptime.'),
  ('coo-operating-leverage-profit-growth', 'operating leverage', 'coo', 'operating-leverage', 3, 3, 5, 'published', 'Revenue is $200M, variable costs are 60% of revenue, and fixed costs are $50M. If revenue rises 10% with the same cost structure, by what percentage does operating profit increase?', 'Enter the percentage increase in operating profit.', '%', 26.67, 0.2, 'Calculate profit before and after the revenue increase, then compare the change with original profit.'),
  ('cfo-gross-margin', 'gross and operating margins', 'cfo', 'gross-and-operating-margins', 1, 1, 2, 'published', 'Revenue is $100M and cost of goods sold is $60M. What is gross margin?', 'Enter gross margin as a percentage.', '%', 40, 0.01, 'Subtract cost of goods sold from revenue, then divide by revenue.'),
  ('cfo-free-cash-flow', 'cash flow', 'cfo', 'cash-flow', 1, 1, 2, 'published', 'Operating cash flow is $35M and capital expenditure is $15M. What is free cash flow?', 'Enter free cash flow.', '$M', 20, 0.01, 'Subtract capital expenditure from operating cash flow.'),
  ('cfo-receivables-days', 'working capital', 'cfo', 'working-capital', 1, 2, 2, 'published', 'Annual credit sales are $360M and average receivables are $30M. Using a 360-day year, what are receivables days?', 'Enter the number of days.', 'days', 30, 0.01, 'Divide receivables by sales, then multiply by 360.'),
  ('cfo-basic-breakeven-units', 'breakeven', 'cfo', 'breakeven', 1, 1, 2, 'published', 'A product sells for $50, has a $30 variable cost, and the business has $200,000 of fixed costs. How many units are needed to break even?', 'Enter the number of units.', 'units', 10000, 0.01, 'Find contribution per unit, then divide fixed costs by it.'),
  ('cfo-budget-variance', 'budget variance', 'cfo', 'budget-variance', 1, 1, 2, 'published', 'Actual operating expense is $54M against a $60M budget. By what percentage is spending below budget?', 'Enter the favorable variance as a percentage of budget.', '%', 10, 0.01, 'Find the $6M difference and divide it by the budget.'),
  ('cfo-net-debt-ebitda', 'financing and leverage', 'cfo', 'financing-and-leverage', 2, 2, 3, 'published', 'A company has $150M of debt, $30M of cash, and $40M of EBITDA. What is net debt to EBITDA?', 'Enter the leverage multiple.', 'x', 3, 0.01, 'Subtract cash from debt, then divide net debt by EBITDA.'),
  ('cfo-roic', 'return on invested capital', 'cfo', 'return-on-invested-capital', 2, 2, 3, 'published', 'EBIT is $50M, the tax rate is 20%, and invested capital is $200M. What is return on invested capital?', 'Enter ROIC as a percentage.', '%', 20, 0.01, 'Apply tax to EBIT to get NOPAT, then divide by invested capital.'),
  ('cfo-diluted-eps', 'dilution and per share value', 'cfo', 'dilution-and-per-share-value', 2, 2, 3, 'published', 'Net income is $48M. The company has 20M existing shares and issues 4M additional shares. What is diluted EPS?', 'Enter earnings per share.', '$ per share', 2, 0.01, 'Add the shares, then divide net income by total shares.'),
  ('cfo-three-year-revenue-forecast', 'revenue and expense forecasting', 'cfo', 'revenue-and-expense-forecasting', 3, 3, 4, 'published', 'Revenue is $200M and is expected to grow 10% annually for three years. What is revenue at the end of year three?', 'Enter revenue in millions of dollars.', '$M', 266.2, 0.2, 'Multiply by 1.10 once for each of the three years.'),
  ('cfo-equity-value-from-multiple', 'valuation multiples', 'cfo', 'valuation-multiples', 3, 3, 4, 'published', 'Revenue is $500M at an 18% EBITDA margin. The business is valued at 7 times EBITDA and has $90M of net debt. What is its equity value?', 'Enter equity value in millions of dollars.', '$M', 540, 0.01, 'Calculate EBITDA, apply the multiple, then subtract net debt.'),
  ('cro-pipeline-coverage', 'pipeline coverage', 'cro', 'pipeline-coverage', 1, 1, 1, 'published', 'A sales team has a $5M quarterly quota and $20M of qualified pipeline. What is pipeline coverage?', 'Enter the coverage multiple.', 'x', 4, 0.01, 'Divide qualified pipeline by quota.'),
  ('cro-lead-to-customer-conversion', 'funnel conversion', 'cro', 'funnel-conversion', 1, 1, 1, 'published', 'A team receives 2,000 qualified leads and wins 200 customers. What is lead-to-customer conversion?', 'Enter conversion as a percentage.', '%', 10, 0.01, 'Divide customers by qualified leads.'),
  ('cro-quota-attainment', 'quota attainment', 'cro', 'quota-attainment', 1, 1, 1, 'published', 'A representative closes $900,000 against a $1.2M quota. What is quota attainment?', 'Enter attainment as a percentage.', '%', 75, 0.01, 'Divide closed revenue by quota.'),
  ('cro-average-contract-value', 'average contract value', 'cro', 'average-contract-value', 1, 1, 1, 'published', 'A team closes $2.4M across 40 contracts. What is average contract value?', 'Enter average contract value in thousands of dollars.', '$k', 60, 0.01, 'Divide total contract value by the number of contracts.'),
  ('cro-basic-commission', 'commissions', 'cro', 'commissions', 1, 1, 1, 'published', 'A salesperson earns a 6% commission on $500,000 of sales. What commission is earned?', 'Enter commission in thousands of dollars.', '$k', 30, 0.01, 'Multiply sales by the commission rate.'),
  ('cro-discount-volume-offset', 'discounting', 'cro', 'discounting', 2, 2, 3, 'published', 'A product sells for $100 with a $60 variable cost. If price is discounted by 10%, by what percentage must unit volume increase to preserve total contribution?', 'Enter the required volume increase.', '%', 33.33, 0.2, 'Compare the old $40 contribution with the new $30 contribution, then find the volume ratio.'),
  ('cro-net-revenue-retention', 'expansion and churn', 'cro', 'expansion-and-churn', 2, 2, 3, 'published', 'A customer base starts the year at $10M ARR, loses $1M to churn, and adds $2M from expansion. What is net revenue retention?', 'Enter net revenue retention as a percentage.', '%', 110, 0.01, 'Adjust starting ARR for churn and expansion, then divide by starting ARR.'),
  ('cro-weighted-win-rate', 'territory planning', 'cro', 'territory-planning', 2, 2, 3, 'published', 'One territory handles 60 opportunities at a 25% win rate. Another handles 40 at a 50% win rate. What is the combined win rate?', 'Enter the combined win rate.', '%', 35, 0.01, 'Calculate wins in each territory, add them, then divide by total opportunities.'),
  ('cro-stage-weighted-forecast', 'revenue forecasting', 'cro', 'revenue-forecasting', 3, 3, 5, 'published', 'A pipeline contains $4M at 25% probability, $3M at 50%, and $2M at 75%. What is the probability-weighted revenue forecast?', 'Enter forecast revenue in millions of dollars.', '$M', 4, 0.01, 'Weight each pipeline amount by its probability, then add the results.'),
  ('cro-rep-capacity-plan', 'sales productivity', 'cro', 'sales-productivity', 3, 3, 5, 'published', 'Each productive representative closes 4 deals per month at an average value of $25,000. New hires spend 3 of 12 months ramping at zero productivity. How many hires are needed to generate $9M in first-year revenue?', 'Enter the number of hires.', 'hires', 10, 0.01, 'Find monthly revenue per productive rep, multiply by nine productive months, then divide the target by first-year revenue per hire.'),
  ('cmo-customer-acquisition-cost', 'customer acquisition cost', 'cmo', 'customer-acquisition-cost', 1, 1, 1, 'published', 'A campaign spends $240,000 and acquires 1,200 customers. What is customer acquisition cost?', 'Enter CAC in dollars.', '$', 200, 0.01, 'Divide campaign spend by acquired customers.'),
  ('cmo-return-on-ad-spend', 'return on advertising spend', 'cmo', 'return-on-advertising-spend', 1, 1, 1, 'published', 'Advertising generates $500,000 of attributed revenue from $100,000 of spend. What is ROAS?', 'Enter the return multiple.', 'x', 5, 0.01, 'Divide attributed revenue by advertising spend.'),
  ('cmo-landing-page-conversion', 'funnel conversion', 'cmo', 'funnel-conversion', 1, 1, 1, 'published', 'A landing page receives 12,000 visitors and produces 600 sign-ups. What is its conversion rate?', 'Enter conversion as a percentage.', '%', 5, 0.01, 'Divide sign-ups by visitors.'),
  ('cmo-basic-market-size', 'market sizing', 'cmo', 'market-sizing', 1, 1, 2, 'published', 'A market has 2 million potential buyers who each spend $40 annually. What is the annual market size?', 'Enter market size in millions of dollars.', '$M', 80, 0.01, 'Multiply buyers by annual spending and express the result in millions.'),
  ('cmo-demand-lift', 'brand and demand lift', 'cmo', 'brand-and-demand-lift', 1, 1, 2, 'published', 'Monthly branded searches rise from 10,000 to 12,000 after a campaign. What is the percentage lift?', 'Enter the percentage lift.', '%', 20, 0.01, 'Find the increase and divide it by the original volume.'),
  ('cmo-gross-profit-ltv', 'customer lifetime value', 'cmo', 'customer-lifetime-value', 2, 2, 3, 'published', 'A customer pays $50 per month, has an 80% gross margin, and remains for 24 months. What is gross-profit lifetime value?', 'Enter lifetime value in dollars.', '$', 960, 0.01, 'Find monthly gross profit, then multiply by customer lifetime.'),
  ('cmo-channel-budget-remaining', 'channel mix', 'cmo', 'channel-mix', 2, 1, 3, 'published', 'A $1M marketing budget allocates 40% to paid search and 25% to events. How much remains for other channels?', 'Enter the remaining budget in thousands of dollars.', '$k', 350, 0.01, 'Calculate both allocations, then subtract them from the total.'),
  ('cmo-incremental-campaign-signups', 'campaign economics', 'cmo', 'campaign-economics', 2, 2, 3, 'published', 'A page receives 20,000 visitors. A campaign raises conversion from 3% to 4.5%. How many incremental sign-ups does it produce?', 'Enter incremental sign-ups.', 'sign-ups', 300, 0.01, 'Find the conversion-rate increase, then apply it to visitor volume.'),
  ('cmo-cohort-payback', 'cohort retention', 'cmo', 'cohort-retention', 3, 3, 4, 'published', 'A cohort costs $120,000 to acquire 600 customers. Each active customer contributes $25 monthly, and 80% remain active after the first month. Using that retained monthly contribution, how many months are needed to recover acquisition spend?', 'Enter payback time in months.', 'months', 10, 0.1, 'Find CAC, retained contribution per original customer, then divide CAC by that contribution.'),
  ('cmo-attribution-incremental-roas', 'attribution', 'cmo', 'attribution', 3, 3, 5, 'published', 'A $200,000 campaign reports $1M of revenue, but analysis estimates that 30% would have occurred anyway. Revenue has a 50% gross margin. What gross profit ROAS did the campaign incrementally generate?', 'Enter incremental gross-profit ROAS.', 'x', 1.75, 0.05, 'Remove baseline revenue, apply gross margin, then divide incremental gross profit by spend.'),
  ('cpo-user-activation', 'activation', 'cpo', 'activation', 1, 1, 1, 'published', 'Of 5,000 new users, 2,000 complete the activation event. What is the activation rate?', 'Enter activation as a percentage.', '%', 40, 0.01, 'Divide activated users by new users.'),
  ('cpo-daily-engagement', 'engagement', 'cpo', 'engagement', 1, 1, 1, 'published', 'A product has 30,000 monthly active users and 6,000 daily active users. What is its DAU-to-MAU ratio?', 'Enter the ratio as a percentage.', '%', 20, 0.01, 'Divide daily active users by monthly active users.'),
  ('cpo-monthly-churn', 'retention and churn', 'cpo', 'retention-and-churn', 1, 1, 1, 'published', 'A subscription product starts with 10,000 customers and loses 500 during the month. What is monthly customer churn?', 'Enter churn as a percentage.', '%', 5, 0.01, 'Divide lost customers by starting customers.'),
  ('cpo-feature-adoption', 'feature adoption', 'cpo', 'feature-adoption', 1, 1, 1, 'published', 'Of 8,000 active users, 2,400 use a new feature. What is feature adoption?', 'Enter adoption as a percentage.', '%', 30, 0.01, 'Divide feature users by active users.'),
  ('cpo-trial-conversion', 'conversion', 'cpo', 'conversion', 1, 1, 1, 'published', 'A product starts 4,000 free trials and converts 600 into paid accounts. What is trial conversion?', 'Enter conversion as a percentage.', '%', 15, 0.01, 'Divide paid conversions by trials.'),
  ('cpo-upgrade-revenue-lift', 'pricing and packaging', 'cpo', 'pricing-and-packaging', 2, 2, 3, 'published', 'A product has 10,000 customers paying $20 monthly. If 25% upgrade to a $32 plan, how much additional monthly revenue is generated?', 'Enter additional monthly revenue in thousands of dollars.', '$k', 30, 0.01, 'Find the price increase, the number upgrading, then multiply them.'),
  ('cpo-ab-test-incremental-activations', 'experiment analysis', 'cpo', 'experiment-analysis', 2, 2, 3, 'published', 'A control converts 20% of 5,000 users. A variant converts 24% of 5,000 users. How many additional activations does the variant produce?', 'Enter additional activations.', 'activations', 200, 0.01, 'Calculate activations for both groups, then subtract.'),
  ('cpo-product-led-expansion', 'product led growth', 'cpo', 'product-led-growth', 2, 2, 3, 'published', 'A product has 2,000 teams with 8 seats each. Usage-driven expansion adds 2 seats to 30% of teams. How many additional seats are created?', 'Enter additional seats.', 'seats', 1200, 0.01, 'Find expanding teams, then multiply by added seats.'),
  ('cpo-retained-cohort-revenue', 'monetization', 'cpo', 'monetization', 3, 3, 4, 'published', 'A cohort begins with 5,000 users. After three monthly retention steps of 80%, 75%, and 80%, how many users remain if each step applies to the previous month''s users?', 'Enter remaining users.', 'users', 2400, 0.01, 'Apply each retention rate sequentially to the remaining cohort.'),
  ('cpo-roadmap-opportunity-cost', 'roadmap trade offs', 'cpo', 'roadmap-trade-offs', 3, 3, 5, 'published', 'Feature A could add 3,000 customers at $20 monthly with a 75% gross margin. Building it delays Feature B by 4 months, and Feature B would contribute $40,000 of gross profit per month. What is Feature A''s annual gross profit minus the delay cost imposed on Feature B?', 'Enter net first-year gross profit in thousands of dollars.', '$k', 380, 0.5, 'Calculate Feature A annual gross profit, calculate four months of Feature B gross profit, then subtract.'),
  ('cto-server-utilization', 'infrastructure capacity', 'cto', 'infrastructure-capacity', 1, 1, 1, 'published', 'A cluster can process 20,000 requests per second and currently handles 15,000. What is utilization?', 'Enter utilization as a percentage.', '%', 75, 0.01, 'Divide current load by maximum capacity.'),
  ('cto-cloud-cost-per-user', 'cloud unit economics', 'cto', 'cloud-unit-economics', 1, 1, 1, 'published', 'Monthly cloud spending is $120,000 for 600,000 active users. What is cloud cost per active user?', 'Enter cost per user in dollars.', '$ per user', 0.2, 0.01, 'Divide cloud spending by active users.'),
  ('cto-error-rate', 'reliability and availability', 'cto', 'reliability-and-availability', 1, 1, 1, 'published', 'A service handles 2 million requests and 10,000 fail. What is the error rate?', 'Enter the error rate as a percentage.', '%', 0.5, 0.01, 'Divide failed requests by total requests.'),
  ('cto-latency-reduction', 'latency and performance', 'cto', 'latency-and-performance', 1, 1, 2, 'published', 'Median latency falls from 250 milliseconds to 200 milliseconds. What is the percentage reduction?', 'Enter the percentage reduction.', '%', 20, 0.01, 'Find the 50-millisecond reduction and divide it by the original latency.'),
  ('cto-engineering-throughput', 'engineering throughput', 'cto', 'engineering-throughput', 1, 1, 1, 'published', 'A team completes 48 production changes over 12 weeks. What is its average weekly throughput?', 'Enter changes per week.', 'changes/week', 4, 0.01, 'Divide changes by weeks.'),
  ('cto-build-versus-buy-payback', 'build versus buy', 'cto', 'build-versus-buy', 2, 2, 3, 'published', 'A vendor costs $40,000 per month. An internal replacement costs $600,000 to build and $10,000 per month to operate. How many months of operating savings recover the build cost?', 'Enter payback time in months.', 'months', 20, 0.1, 'Find monthly savings versus the vendor, then divide build cost by savings.'),
  ('cto-parallel-latency-budget', 'architecture trade offs', 'cto', 'architecture-trade-offs', 2, 2, 3, 'published', 'A request has 40 ms of fixed work plus three parallel services taking 60 ms, 90 ms, and 70 ms. Ignoring overhead, what is total request latency?', 'Enter total latency in milliseconds.', 'ms', 130, 0.01, 'Parallel work takes as long as the slowest service, then add fixed work.'),
  ('cto-energy-consumption', 'energy and power', 'cto', 'energy-and-power', 2, 2, 3, 'published', 'A data center draws 5 megawatts continuously for 24 hours. How much energy does it consume in one day?', 'Enter energy in megawatt-hours.', 'MWh', 120, 0.01, 'Energy equals power multiplied by time.'),
  ('cto-redundant-system-availability', 'reliability and availability', 'cto', 'reliability-and-availability', 3, 3, 4, 'published', 'Two independent services each have 90% availability. The system works if either service is available. What is total system availability?', 'Enter availability as a percentage.', '%', 99, 0.05, 'Find the probability both services fail, then subtract it from 100%.'),
  ('cto-scaling-compute-cost', 'scaling laws', 'cto', 'scaling-laws', 3, 3, 4, 'published', 'Traffic grows from 2 million to 5 million daily requests. Compute cost is $40,000 at the original traffic and scales with the square of the traffic ratio. What is the new compute cost?', 'Enter compute cost in thousands of dollars.', '$k', 250, 0.5, 'Find the traffic ratio, square it, then multiply original cost by that factor.'),
  ('cio-license-utilization', 'systems utilization', 'cio', 'systems-utilization', 1, 1, 1, 'published', 'A company pays for 5,000 software licenses and 4,000 are active. What is license utilization?', 'Enter utilization as a percentage.', '%', 80, 0.01, 'Divide active licenses by purchased licenses.'),
  ('cio-automation-hours-saved', 'automation returns', 'cio', 'automation-returns', 1, 1, 2, 'published', 'An automation saves 15 minutes on each of 800 weekly tasks. How many work hours does it save per week?', 'Enter hours saved.', 'hours', 200, 0.01, 'Multiply minutes saved by tasks, then convert minutes to hours.'),
  ('cio-data-error-rate', 'data quality', 'cio', 'data-quality', 1, 1, 1, 'published', 'A dataset contains 50,000 records and 1,000 have critical errors. What is the critical error rate?', 'Enter the error rate as a percentage.', '%', 2, 0.01, 'Divide erroneous records by total records.'),
  ('cio-model-precision', 'model precision and recall', 'cio', 'model-precision-and-recall', 1, 1, 1, 'published', 'A model flags 500 cases, of which 400 are genuinely positive. What is precision?', 'Enter precision as a percentage.', '%', 80, 0.01, 'Divide true positives by all flagged cases.'),
  ('cio-inference-unit-cost', 'ai inference economics', 'cio', 'ai-inference-economics', 1, 1, 1, 'published', 'One million AI requests cost $20,000. What is the cost per thousand requests?', 'Enter cost per thousand requests.', '$', 20, 0.01, 'Divide total cost by the number of thousand-request groups.'),
  ('cio-storage-growth', 'storage and compute growth', 'cio', 'storage-and-compute-growth', 2, 2, 3, 'published', 'Stored data starts at 80 TB and grows 25% in year one and 20% in year two. How much storage is required after two years?', 'Enter storage in terabytes.', 'TB', 120, 0.1, 'Apply each annual growth rate to the prior year''s storage.'),
  ('cio-vendor-switch-payback', 'vendor economics', 'cio', 'vendor-economics', 2, 2, 3, 'published', 'A new vendor saves $25,000 per month but requires a $300,000 migration. How many months are needed to recover the migration cost?', 'Enter payback time in months.', 'months', 12, 0.1, 'Divide migration cost by monthly savings.'),
  ('cio-migration-team-capacity', 'migration planning', 'cio', 'migration-planning', 2, 2, 3, 'published', 'A migration covers 240 applications. Four teams can each migrate 5 applications per month. How many months will the program take?', 'Enter program duration in months.', 'months', 12, 0.1, 'Find combined monthly capacity, then divide applications by that capacity.'),
  ('cio-model-f1-score', 'model precision and recall', 'cio', 'model-precision-and-recall', 3, 3, 4, 'published', 'A model has 80% precision and 60% recall. What is its F1 score?', 'Enter the F1 score as a percentage.', '%', 68.57, 0.2, 'Multiply precision and recall, double the result, then divide by their sum.'),
  ('cio-risk-adjusted-automation-value', 'cybersecurity exposure', 'cio', 'cybersecurity-exposure', 3, 3, 5, 'published', 'An automation saves $600,000 annually but creates a 10% annual probability of a $2M incident. It also costs $150,000 annually to operate. What is expected annual net value?', 'Enter expected net value in thousands of dollars.', '$k', 250, 0.5, 'Subtract expected incident loss and annual operating cost from annual savings.'),
  ('chro-headcount-gap', 'headcount planning', 'chro', 'headcount-planning', 1, 1, 1, 'published', 'A company has 500 employees and plans to reach 550. How many additional employees must it hire?', 'Enter the additional headcount.', 'employees', 50, 0.01, 'Subtract current headcount from planned headcount.'),
  ('chro-interview-conversion', 'hiring funnels', 'chro', 'hiring-funnels', 1, 1, 1, 'published', 'A company receives 1,000 qualified applications and interviews 100 candidates. What is application-to-interview conversion?', 'Enter conversion as a percentage.', '%', 10, 0.01, 'Divide interviewed candidates by qualified applications.'),
  ('chro-annual-attrition', 'attrition and retention', 'chro', 'attrition-and-retention', 1, 1, 1, 'published', 'A company starts the year with 1,000 employees and 50 leave. What is annual attrition?', 'Enter attrition as a percentage.', '%', 5, 0.01, 'Divide departures by starting headcount.'),
  ('chro-salary-increase-cost', 'compensation', 'chro', 'compensation', 1, 1, 2, 'published', 'Two hundred employees each receive a $5,000 annual salary increase. What is the additional annual salary cost?', 'Enter cost in millions of dollars.', '$M', 1, 0.01, 'Multiply employees by the increase and convert to millions.'),
  ('chro-span-of-control', 'span of control', 'chro', 'span-of-control', 1, 1, 1, 'published', 'Fifteen managers collectively supervise 120 employees. What is the average span of control?', 'Enter reports per manager.', 'reports', 8, 0.01, 'Divide employees by managers.'),
  ('chro-loaded-workforce-cost', 'organizational cost', 'chro', 'organizational-cost', 2, 2, 3, 'published', 'A company employs 400 people at an average salary of $80,000. Benefits equal 25% of salary. What is total annual workforce cost?', 'Enter total cost in millions of dollars.', '$M', 40, 0.01, 'Calculate salary cost, calculate benefits, then add them.'),
  ('chro-training-payback', 'training returns', 'chro', 'training-returns', 2, 2, 2, 'published', 'A training program costs $240,000 and is expected to save $40,000 per month. How many months are required for payback?', 'Enter payback time in months.', 'months', 6, 0.1, 'Divide program cost by monthly savings.'),
  ('chro-leadership-representation-hires', 'diversity representation', 'chro', 'diversity-representation', 2, 2, 3, 'published', 'A company has 80 leaders, including 20 women. It adds 20 leadership roles and wants women to represent 30% of the new total. How many of the new roles must be filled by women?', 'Enter the required number of hires.', 'hires', 10, 0.01, 'Find the target number of women at 100 leaders, then subtract the current number.'),
  ('chro-retention-program-value', 'attrition and retention', 'chro', 'attrition-and-retention', 3, 3, 5, 'published', 'A company has 1,000 employees, 12% annual attrition, and a $15,000 replacement cost per departure. A $300,000 program halves attrition. What is the program''s annual net saving?', 'Enter net savings in thousands of dollars.', '$k', 600, 0.5, 'Calculate current replacement cost, halve it, then subtract program cost from avoided cost.'),
  ('chro-layered-organization-cost', 'organizational cost', 'chro', 'organizational-cost', 3, 3, 5, 'published', 'A company has 8 business units. Each has one $180,000 director, five $120,000 managers, and ten $70,000 staff members per manager. What is total annual salary cost?', 'Enter total cost in millions of dollars.', '$M', 34.24, 0.05, 'Calculate each role''s cost per unit, add them, then multiply by eight units.'),
  ('supply-chain-demand-growth', 'demand planning', 'supply_chain', 'demand-planning', 1, 1, 1, 'published', 'Monthly demand is 20,000 units and is forecast to grow 15%. How many units should be planned?', 'Enter planned monthly units.', 'units', 23000, 0.01, 'Add 15% of current demand to current demand.'),
  ('supply-chain-inventory-days', 'inventory levels', 'supply_chain', 'inventory-levels', 1, 1, 2, 'published', 'Inventory is $5M and annual cost of goods sold is $60M. Using a 360-day year, how many inventory days are held?', 'Enter inventory days.', 'days', 30, 0.01, 'Divide inventory by annual cost of goods sold, then multiply by 360.'),
  ('supply-chain-volume-discount', 'purchase volume discounts', 'supply_chain', 'purchase-volume-discounts', 1, 1, 1, 'published', 'A supplier gives a 10% discount on a $500,000 order. What is the discount value?', 'Enter the discount in thousands of dollars.', '$k', 50, 0.01, 'Multiply order value by the discount rate.'),
  ('supply-chain-logistics-cost-per-unit', 'logistics costs', 'supply_chain', 'logistics-costs', 1, 1, 1, 'published', 'Shipping 40,000 units costs $120,000. What is logistics cost per unit?', 'Enter cost per unit.', '$', 3, 0.01, 'Divide shipping cost by units shipped.'),
  ('supply-chain-production-yield', 'production yield', 'supply_chain', 'production-yield', 1, 1, 2, 'published', 'A supplier produces 5,000 components and 4,800 pass inspection. What is production yield?', 'Enter yield as a percentage.', '%', 96, 0.01, 'Divide accepted components by total components.'),
  ('supply-chain-reorder-coverage', 'safety stock', 'supply_chain', 'safety-stock', 2, 1, 3, 'published', 'Daily demand is 200 units, supplier lead time is 5 days, and policy requires 2 additional days of safety stock. How many units should the reorder level cover?', 'Enter the reorder level.', 'units', 1400, 0.01, 'Add lead time and safety days, then multiply by daily demand.'),
  ('supply-chain-make-versus-buy', 'make versus buy', 'supply_chain', 'make-versus-buy', 2, 2, 3, 'published', 'Making 50,000 units costs $18 each plus $300,000 of fixed cost. A supplier offers $27 per unit. How much does making save per unit?', 'Enter savings per unit.', '$ per unit', 3, 0.01, 'Allocate fixed cost per unit, add variable cost, then compare with supplier price.'),
  ('supply-chain-weighted-supplier-price', 'supplier pricing', 'supply_chain', 'supplier-pricing', 2, 2, 3, 'published', 'Seventy percent of 10,000 units are bought at $10 each and the rest at $14. What is the weighted average purchase price?', 'Enter average price per unit.', '$ per unit', 11.2, 0.05, 'Weight each supplier price by its volume share, then add.'),
  ('supply-chain-yield-adjusted-input-cost', 'production yield', 'supply_chain', 'production-yield', 3, 3, 4, 'published', 'A plant needs 900 good units. Production yield is 90%. Each started unit requires $8 of material and $4 of conversion cost. What total input and conversion cost is required?', 'Enter total cost in thousands of dollars.', '$k', 12, 0.01, 'Reverse-solve the units that must be started, then apply both unit costs.'),
  ('supply-chain-landed-cost-per-good-unit', 'logistics costs', 'supply_chain', 'logistics-costs', 3, 3, 5, 'published', 'A company buys 20,000 units at $30 each, pays $4 freight per unit and a 10% duty on purchase price. Five percent of units are defective. What is landed cost per good unit?', 'Enter landed cost per good unit.', '$', 38.95, 0.1, 'Add purchase, freight, and duty costs, then divide total landed cost by good units.'),
  ('risk-basic-expected-loss', 'expected loss', 'risk', 'expected-loss', 1, 1, 2, 'published', 'An event has a 5% probability of causing a $2M loss. What is the expected loss?', 'Enter expected loss in thousands of dollars.', '$k', 100, 0.01, 'Multiply loss size by its probability.'),
  ('risk-exposure-concentration', 'exposure concentration', 'risk', 'exposure-concentration', 1, 1, 1, 'published', 'One customer represents $40M of a $100M credit portfolio. What is the concentration?', 'Enter concentration as a percentage.', '%', 40, 0.01, 'Divide customer exposure by total portfolio exposure.'),
  ('risk-stressed-revenue', 'scenario analysis', 'risk', 'scenario-analysis', 1, 1, 1, 'published', 'Revenue is $100M and a stress scenario reduces it by 20%. What is stressed revenue?', 'Enter stressed revenue.', '$M', 80, 0.01, 'Subtract 20% of revenue from the original amount.'),
  ('risk-adjusted-simple-return', 'risk adjusted returns', 'risk', 'risk-adjusted-returns', 1, 1, 1, 'published', 'An investment offers a 12% return with an expected loss of 3% of invested capital. What is the simple risk-adjusted return?', 'Enter the risk-adjusted return.', '%', 9, 0.01, 'Subtract expected loss rate from expected return.'),
  ('risk-operational-incident-rate', 'operational risk', 'risk', 'operational-risk', 1, 1, 1, 'published', 'Twenty material incidents occur across 1,000 operating sites. What is the incident rate?', 'Enter the incident rate as a percentage.', '%', 2, 0.01, 'Divide incidents by sites.'),
  ('risk-credit-expected-loss', 'credit risk', 'risk', 'credit-risk', 2, 2, 3, 'published', 'A $1M loan has a 2% probability of default and a 40% recovery rate after default. What is expected credit loss?', 'Enter expected loss in thousands of dollars.', '$k', 12, 0.05, 'Find loss after recovery, then multiply by default probability.'),
  ('risk-insurance-economic-benefit', 'insurance economics', 'risk', 'insurance-economics', 2, 2, 3, 'published', 'A $500,000 loss has a 10% annual probability. Full insurance costs $40,000 annually. What expected annual benefit does insurance provide before considering risk aversion?', 'Enter expected benefit in thousands of dollars.', '$k', 10, 0.01, 'Calculate expected uninsured loss, then subtract the premium.'),
