  ('risk-independent-event-probability', 'probability of loss', 'risk', 'probability-of-loss', 3, 3, 4, 'published', 'Two independent risks have probabilities of 10% and 20%. What is the probability that at least one occurs?', 'Enter the probability as a percentage.', '%', 28, 0.05, 'Find the probability neither occurs, then subtract it from 100%.'),
  ('risk-stressed-liquidity-buffer', 'sensitivity and stress tests', 'risk', 'sensitivity-and-stress-tests', 3, 2, 4, 'published', 'A company has $50M of cash and a $30M undrawn facility. A stress scenario creates $20M of monthly cash outflow for three months and requires a $15M debt repayment. What liquidity remains?', 'Enter remaining liquidity in millions of dollars.', '$M', 5, 0.01, 'Add available liquidity, subtract three months of outflows, then subtract debt repayment.');
